package com.digitrob.digitdns.core.network

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import retrofit2.http.GET

/**
 * The v3 control-plane surface, generated by hand from
 * internal/api/openapi/v3.json.
 *
 * Phase 0 declares only the two keyless meta calls, which is enough to prove the
 * stack end to end (client → converter → real endpoint) without the auth layer. The
 * remaining paths — auth, clients, policies, custom-groups, rules, access,
 * upstreams, settings, tls, stats, diagnostics, system — are added per phase.
 *
 * Every path is the *suffix* after the install's hidden admin path; the client
 * rewrites the host and prepends `/<admin-path>/api/v3` at call time.
 */
interface DigitDnsApi {

    /** `GET /api/v3/version` — build version, sync hash, API generation. Keyless. */
    @GET("version")
    suspend fun version(): VersionDto
}

@Serializable
data class VersionDto(
    val version: String = "",
    @SerialName("display") val display: String = "",
    val hash: String = "",
    val commit: String = "",
    val api: String = "",
)
